ZTEST(ringbuffer_api, test_byte_put_free)
{
	uint8_t indata[] = {1, 2, 3, 4, 5};
	int err;
	uint32_t granted;
	uint8_t *data;

	ring_buf_init(&ringbuf_raw, RINGBUFFER_SIZE, ringbuf_raw.buffer);

	/* Ring buffer is empty */
	granted = ring_buf_get_claim(&ringbuf_raw, &data, RINGBUFFER_SIZE);
	zassert_true(granted == 0U);

	for (int i = 0; i < 10; i++) {
		uint32_t total_read = 0;
		uint32_t to_read = RINGBUFFER_SIZE - 2;

		ring_buf_reset(&ringbuf_raw);
		ring_buf_put(&ringbuf_raw, indata, to_read);

		while (total_read < to_read) {
			granted = ring_buf_get_claim(&ringbuf_raw, &data,
						       to_read - total_read);
			zassert_true(granted > 0);
			zassert_true(memcmp(&indata[total_read], data, granted) == 0);

			err = ring_buf_get_finish(&ringbuf_raw, granted);
			zassert_true(err == 0);

			total_read += granted;
		}

		/* All data read and freed, next claim should fail. */
		granted = ring_buf_get_claim(&ringbuf_raw, &data, 1);
		zassert_true(granted == 0);
	}
}
